import {useEffect,useMemo,useState} from 'react';
import {MessageCircle,RefreshCw,Send,X} from 'lucide-react';
import {listCommunicationActivity,listCommunicationTemplates,openWhatsApp} from '../../lib/practiceOperationsApi';

const BUILT_INS=[
  {code:'ONBOARDING_INVITATION',label:'Onboarding invitation',body:'Hi {{client_name}}, please complete your onboarding using this secure link: {{onboarding_link}}. It will help me review your information before our consultation.'},
  {code:'ONBOARDING_REMINDER',label:'Onboarding reminder',body:'Hi {{client_name}}, this is a reminder to complete your secure onboarding: {{onboarding_link}}.'},
  {code:'APPOINTMENT_REMINDER',label:'Appointment reminder',body:'Hi {{client_name}}, a reminder for your {{consultation_label}} on {{date}} at {{time}}.'},
  {code:'FOLLOW_UP_REMINDER',label:'Follow-up reminder',body:'Hi {{client_name}}, this is a reminder about your follow-up with {{consultant_name}}.'},
  {code:'DIET_PLAN_READY',label:'Published plan ready',body:'Hi {{client_name}}, your published plan is ready: {{plan_link}}.'},
  {code:'PROGRESS_CHECK_IN',label:'Progress check-in',body:'Hi {{client_name}}, how are you progressing? Please share your update when convenient.'},
  {code:'LAB_REPORT_REQUEST',label:'Lab report request',body:'Hi {{client_name}}, please upload your report through the secure client link.'},
];

function applyTemplate(value,client,context){return Object.entries({client_name:client?.displayName||'',consultant_name:context.consultantName||'',practice_name:context.practiceName||'',onboarding_link:client?.invitationUrl||'',plan_link:context.planLink||'',date:context.date||'',time:context.time||'',consultation_label:context.consultationLabel||'consultation'}).reduce((text,[key,replacement])=>text.replaceAll(`{{${key}}}`,replacement),value);}

export function ExternalCommunicationWorkspace({clients,practiceName,consultantName,terminology}){
  const [activity,setActivity]=useState([]);const [templates,setTemplates]=useState([]);const [loading,setLoading]=useState(true);const [error,setError]=useState('');const [composer,setComposer]=useState(null);
  async function load(){setLoading(true);setError('');try{const [templatePage,activityPage]=await Promise.all([listCommunicationTemplates(),listCommunicationActivity()]);setTemplates(templatePage.items?.length?templatePage.items:BUILT_INS);setActivity(activityPage.items||[]);}catch(reason){setError(reason.message||'Communication activity could not load.');setTemplates(BUILT_INS);}finally{setLoading(false)}}
  useEffect(()=>{void load()},[]);
  return <div className="space-y-6 pb-24 lg:pb-8"><header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-blue-700">Communication</p><h2 className="mt-2 text-3xl font-bold tracking-tight">Client communication</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-600">Preview an editable message, then open WhatsApp. Activity records that WhatsApp was opened—not sent, delivered, or read.</p></div><button onClick={()=>setComposer({})} className="min-h-11 rounded-xl bg-[#0c1728] px-4 font-bold text-white"><MessageCircle className="mr-2 inline" size={18}/>New WhatsApp message</button></header>
    {error&&<div role="alert" className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-800">{error}<button onClick={load} className="ml-3 font-bold"><RefreshCw className="inline" size={15}/> Retry</button></div>}
    <section className="grid gap-4 lg:grid-cols-[1fr_1.2fr]"><div className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="text-lg font-bold">Message templates</h3><div className="mt-4 space-y-2">{templates.map(template=><button key={template.code} onClick={()=>setComposer({template})} className="min-h-12 w-full rounded-xl border border-slate-200 px-4 text-left text-sm font-semibold hover:border-blue-300 hover:bg-blue-50">{template.label}</button>)}</div></div><div className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="text-lg font-bold">Recent activity</h3>{loading?<p role="status" className="mt-5 text-sm text-slate-500">Loading activity…</p>:activity.length?<div className="mt-4 space-y-3">{activity.map(item=><article key={item.id} className="rounded-2xl bg-slate-50 p-4"><p className="font-semibold">WhatsApp opened for {item.purpose}</p><p className="mt-1 text-xs text-slate-500">{new Date(item.created_at).toLocaleString()}</p></article>)}</div>:<p className="mt-5 text-sm text-slate-500">No communication activity yet.</p>}</div></section>
    {composer&&<WhatsAppComposer clients={clients} templates={templates} initialTemplate={composer.template} context={{practiceName,consultantName,consultationLabel:terminology?.consultation}} onClose={()=>setComposer(null)} onOpened={async()=>{setComposer(null);await load()}}/>}
  </div>;
}

function WhatsAppComposer({clients,templates,initialTemplate,context,onClose,onOpened}){const [clientId,setClientId]=useState(clients[0]?.id||'');const [templateCode,setTemplateCode]=useState(initialTemplate?.code||templates[0]?.code||'');const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');const client=useMemo(()=>clients.find(item=>item.id===clientId),[clients,clientId]);const template=useMemo(()=>templates.find(item=>item.code===templateCode),[templates,templateCode]);useEffect(()=>{setMessage(applyTemplate(template?.body||'',client,context))},[template,client,context]);async function submit(event){event.preventDefault();setBusy(true);setError('');try{await openWhatsApp({client_id:client.id,template_code:templateCode||null,purpose:(template?.label||'client message').toLowerCase(),phone:client.mobile||'',message});await onOpened()}catch(reason){setError(reason.message||'WhatsApp could not be opened.');setBusy(false)}}return <div className="fixed inset-0 z-50 flex items-end bg-slate-950/45 sm:items-stretch sm:justify-end" onClick={onClose}><form onSubmit={submit} onClick={event=>event.stopPropagation()} role="dialog" aria-modal="true" aria-labelledby="whatsapp-title" className="max-h-[92vh] w-full overflow-y-auto rounded-t-3xl bg-white p-5 pb-[calc(1.25rem+env(safe-area-inset-bottom))] sm:h-full sm:max-h-none sm:max-w-lg sm:rounded-none sm:p-8"><div className="flex items-center justify-between"><h2 id="whatsapp-title" className="text-2xl font-bold">WhatsApp message</h2><button type="button" onClick={onClose} aria-label="Close" className="grid h-11 w-11 place-items-center rounded-xl border"><X/></button></div>{error&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm text-red-700">{error}</p>}<label className="mt-6 block text-sm font-semibold">Client<select required value={clientId} onChange={event=>setClientId(event.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3"><option value="">Select client</option>{clients.map(item=><option key={item.id} value={item.id}>{item.displayName}</option>)}</select></label><label className="mt-5 block text-sm font-semibold">Template<select value={templateCode} onChange={event=>setTemplateCode(event.target.value)} className="mt-2 min-h-12 w-full rounded-xl border px-3">{templates.map(item=><option key={item.code} value={item.code}>{item.label}</option>)}</select></label><label className="mt-5 block text-sm font-semibold">To<input readOnly value={client?.mobile||'No mobile number'} className="mt-2 min-h-12 w-full rounded-xl border bg-slate-50 px-3"/></label><label className="mt-5 block text-sm font-semibold">Message<textarea required rows={8} value={message} onChange={event=>setMessage(event.target.value)} className="mt-2 w-full rounded-xl border p-3"/></label><p className="mt-3 text-xs leading-5 text-slate-500">You will review the message in WhatsApp and press Send yourself.</p><div className="sticky bottom-0 mt-8 flex gap-3 bg-white py-3"><button type="button" onClick={onClose} className="min-h-12 flex-1 rounded-xl border font-semibold">Cancel</button><button disabled={busy||!client?.mobile||!message.trim()} className="min-h-12 flex-1 rounded-xl bg-emerald-700 font-bold text-white disabled:opacity-50"><Send className="mr-2 inline" size={17}/>{busy?'Opening…':'Open WhatsApp'}</button></div></form></div>}
